#include <stdio.h>
#include <stdlib.h>

#define INBUF_SIZE (1 << 20)
#define OUTBUF_SIZE (1 << 20)

static char inbuf[INBUF_SIZE];
static int inpos = 0, insize = 0;

static char outbuf[OUTBUF_SIZE];
static int outpos = 0;

static inline int read_char(void) {
    if (inpos >= insize) {
        insize = (int)fread(inbuf, 1, INBUF_SIZE, stdin);
        inpos = 0;
        if (insize == 0) return EOF;
    }
    return (unsigned char)inbuf[inpos++];
}

static int read_int(void) {
    int c, x = 0;
    do {
        c = read_char();
    } while (c <= ' ' && c != EOF);

    while (c > ' ' && c != EOF) {
        x = x * 10 + (c - '0');
        c = read_char();
    }
    return x;
}

static char read_op(void) {
    int c;
    do {
        c = read_char();
    } while (c <= ' ' && c != EOF);
    return (char)c;
}

static inline void flush_out(void) {
    if (outpos > 0) {
        fwrite(outbuf, 1, outpos, stdout);
        outpos = 0;
    }
}

static inline void write_char(char c) {
    if (outpos >= OUTBUF_SIZE) flush_out();
    outbuf[outpos++] = c;
}

static void write_int(int x) {
    char s[12];
    int n = 0;

    if (x == 0) {
        write_char('0');
        return;
    }

    while (x > 0) {
        s[n++] = (char)('0' + (x % 10));
        x /= 10;
    }

    while (n--) {
        write_char(s[n]);
    }
}

int main(void) {
    int N = read_int();
    int M = read_int();
    int P = read_int();

    int *row = (int *)malloc((size_t)(N + 1) * sizeof(int));
    int *col = (int *)malloc((size_t)(M + 1) * sizeof(int));

    for (int i = 1; i <= N; ++i) row[i] = i;
    for (int j = 1; j <= M; ++j) col[j] = j;

    for (int k = 0; k < P; ++k) {
        char op = read_op();
        int a = read_int();
        int b = read_int();

        if (op == 'L') {
            int tmp = row[a];
            row[a] = row[b];
            row[b] = tmp;
        } else {
            int tmp = col[a];
            col[a] = col[b];
            col[b] = tmp;
        }
    }

    for (int i = 1; i <= N; ++i) {
        int base = (row[i] - 1) * M;

        for (int j = 1; j <= M; ++j) {
            if (j > 1) write_char(' ');
            write_int(base + col[j]);
        }

        write_char('\n');
    }

    flush_out();

    free(row);
    free(col);

    return 0;
}
